exercises.solutionCode:
#include <stdint.h>

#define I2C_DIR_WRITE 0
#define I2C_DIR_READ  1

int i2c_build_addr_byte(int addr, int dir)
{
    if (addr < 0 || addr > 0x7F) {
        return -1;
    }
    if (dir != I2C_DIR_WRITE && dir != I2C_DIR_READ) {
        return -1;
    }
    if (addr == 0 && dir == I2C_DIR_READ) {
        return -1;
    }
    return (int)(((uint8_t)addr << 1) | (uint8_t)dir);
}
